/**
 * Generate schema from your API instance
 */
declare function generate(args: {
    /**
     * Current working directory
     */
    cwd: string;
    /**
     * Filename of the schema to process, default is `storeApiSchema.json` or `adminApiSchema.json` depending on the `apiType` parameter
     */
    filename?: string;
    /**
     * Type of the API to generate types for
     */
    apiType: "store" | "admin";
    /**
     * Debug mode, display additional information and generates additional files, not needed for the regular usage
     */
    debug: boolean;
    /**
     * Log patches, display information about applied patches while generating types
     */
    logPatches: boolean;
}): Promise<void>;

/**
 * Load JSON schema from your API instance. You need to have proper .env file with the following values:
 *
 * For `store` API:
 * - OPENAPI_JSON_URL
 * - OPENAPI_ACCESS_KEY
 *
 * For `admin` API:
 * - OPENAPI_JSON_URL
 * - SHOPWARE_ADMIN_USERNAME
 * - SHOPWARE_ADMIN_PASSWORD
 *
 */
declare function loadSchema(args: {
    /**
     * Current working directory
     */
    cwd: string;
    /**
     * Filename to save the downloaded schema, default is `storeApiSchema.json` or `adminApiSchema.json` depending on the `apiType` parameter
     */
    filename?: string;
    /**
     * Type of the API to generate types for
     */
    apiType: "store" | "admin";
}): Promise<void>;

/**
 * Validate JSON schema with the ruleset and parser
 */
declare function validateJson(args: {
    /**
     * Current working directory
     */
    cwd: string;
    /**
     * Filename of the schema to process, default is `storeApiSchema.json` or `adminApiSchema.json` depending on the `apiType` parameter
     */
    filename?: string;
    /**
     * Type of the API to validate
     */
    apiType: "store" | "admin";
    /**
     * Log patches, display information about applied patches while generating types
     */
    logPatches: boolean;
    debug: boolean;
}): Promise<void>;

export { generate, loadSchema, validateJson };
